package com.dpworld.fms.api;
import com.dpworld.fms.domain.GeoPoint;import com.dpworld.fms.routing.*;import java.sql.Timestamp;import java.time.Instant;import java.util.UUID;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
@Service public class TelemetryMapMatchingService{private final RoutingGraphRepository graphs;private final JdbcTemplate jdbc;private final double maxDistance,maxHeadingDelta,minimumConfidence;public TelemetryMapMatchingService(RoutingGraphRepository graphs,JdbcTemplate jdbc,@Value("${dpwfms.routing.map-matching.maximum-distance-metres:35}")double maxDistance,@Value("${dpwfms.routing.map-matching.maximum-heading-delta-degrees:100}")double maxHeadingDelta,@Value("${dpwfms.routing.map-matching.minimum-confidence:0.35}")double minimumConfidence){this.graphs=graphs;this.jdbc=jdbc;this.maxDistance=maxDistance;this.maxHeadingDelta=maxHeadingDelta;this.minimumConfidence=minimumConfidence;}public void match(UUID assetId,double latitude,double longitude,double heading,Instant occurredAt){var active=graphs.findActiveApproved();if(active.isEmpty()){jdbc.update("UPDATE assets SET matched_node_id=NULL,matched_segment_id=NULL,matched_at=?,match_confidence=0,match_metadata=jsonb_build_object('reason','NO_ACTIVE_APPROVED_GRAPH') WHERE id=?",Timestamp.from(occurredAt),assetId);return;}var graph=active.get();String previous=jdbc.query("SELECT matched_segment_id::text FROM assets WHERE id=?",rs->rs.next()?rs.getString(1):null,assetId);GpsMapMatcher.Match result=new GpsMapMatcher(graph.nodes(),graph.segments(),maxDistance).match(new GeoPoint(latitude,longitude),heading,previous);if(result==null||result.headingDelta()>maxHeadingDelta||result.confidence()<minimumConfidence){jdbc.update("UPDATE assets SET matched_node_id=NULL,matched_segment_id=NULL,matched_at=?,match_confidence=0,match_metadata=jsonb_build_object('reason','NO_MATCH') WHERE id=?",Timestamp.from(occurredAt),assetId);return;}jdbc.update("UPDATE assets SET matched_node_id=(SELECT id FROM map_nodes WHERE graph_version_id=? AND code=?),matched_segment_id=?::uuid,matched_at=?,match_confidence=?,match_metadata=jsonb_build_object('distanceMetres',?,'headingDelta',?,'snappedLatitude',?,'snappedLongitude',?) WHERE id=?",graph.id(),result.nodeId(),result.segmentId(),Timestamp.from(occurredAt),result.confidence(),result.distanceMetres(),result.headingDelta(),result.snappedPosition().latitude(),result.snappedPosition().longitude(),assetId);}}
